```python
#!/usr/bin/env python3
"""JSON normalizer: strict parse + canonical whitespace-free output.

Run:   echo '{"a":1,"b":[2,3]}' | python3 main.py
Input: one JSON value on stdin (surrounding whitespace allowed).
Output: canonical text with no whitespace, or a single line "ERR".
"""
import sys


class ParseError(Exception):
    pass


class Parser:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def err(self):
        raise ParseError()

    def peek(self):
        return self.s[self.i] if self.i < self.n else ''

    def skip_ws(self):
        while self.i < self.n and self.s[self.i] in ' \t\n\r':
            self.i += 1

    def parse(self):
        self.skip_ws()
        v = self.parse_value()
        self.skip_ws()
        if self.i != self.n:
            self.err()
        return v

    def parse_value(self):
        c = self.peek()
        if c == '{':
            return self.parse_object()
        if c == '[':
            return self.parse_array()
        if c == '"':
            return self.parse_string()
        if c == 't':
            return self.parse_lit('true', True)
        if c == 'f':
            return self.parse_lit('false', False)
        if c == 'n':
            return self.parse_lit('null', None)
        if c == '-' or c.isdigit():
            return self.parse_number()
        self.err()

    def parse_lit(self, word, val):
        if self.s[self.i:self.i + len(word)] != word:
            self.err()
        self.i += len(word)
        return val

    def parse_number(self):
        start = self.i
        if self.peek() == '-':
            self.i += 1
        if self.peek() == '0':
            self.i += 1
            if self.i < self.n and self.s[self.i].isdigit():
                self.err()
        elif self.peek().isdigit() and self.peek() != '0':
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
        else:
            self.err()
        if self.i == start:
            self.err()
        return int(self.s[start:self.i])

    def parse_string(self):
        if self.peek() != '"':
            self.err()
        self.i += 1
        out = []
        while True:
            if self.i >= self.n:
                self.err()
            c = self.s[self.i]
            if c == '"':
                self.i += 1
                return ''.join(out)
            if c == '\\':
                self.i += 1
                if self.i >= self.n:
                    self.err()
                e = self.s[self.i]
                if e == '"':
                    out.append('"'); self.i += 1
                elif e == '\\':
                    out.append('\\'); self.i += 1
                elif e == '/':
                    out.append('/'); self.i += 1
                elif e == 'n':
                    out.append('\n'); self.i += 1
                elif e == 't':
                    out.append('\t'); self.i += 1
                elif e == 'u':
                    hexs = self.s[self.i + 1:self.i + 5]
                    if len(hexs) != 4 or any(ch not in '0123456789abcdefABCDEF' for ch in hexs):
                        self.err()
                    cp = int(hexs, 16)
                    if cp < 0x20:
                        self.err()
                    out.append(chr(cp))
                    self.i += 5
                else:
                    self.err()
            else:
                if ord(c) < 0x20:
                    self.err()
                out.append(c)
                self.i += 1

    def parse_array(self):
        self.i += 1  # consume [
        self.skip_ws()
        arr = []
        if self.peek() == ']':
            self.i += 1
            return arr
        while True:
            self.skip_ws()
            arr.append(self.parse_value())
            self.skip_ws()
            c = self.peek()
            if c == ',':
                self.i += 1
                continue
            if c == ']':
                self.i += 1
                return arr
            self.err()

    def parse_object(self):
        self.i += 1  # consume {
        self.skip_ws()
        obj = {}
        if self.peek() == '}':
            self.i += 1
            return obj
        while True:
            self.skip_ws()
            if self.peek() != '"':
                self.err()
            key = self.parse_string()
            self.skip_ws()
            if self.peek() != ':':
                self.err()
            self.i += 1
            self.skip_ws()
            obj[key] = self.parse_value()
            self.skip_ws()
            c = self.peek()
            if c == ',':
                self.i += 1
                continue
            if c == '}':
                self.i += 1
                return obj
            self.err()


def emit(v, buf):
    if v is None:
        buf.append('null')
    elif v is True:
        buf.append('true')
    elif v is False:
        buf.append('false')
    elif isinstance(v, int):
        buf.append(str(v))
    elif isinstance(v, str):
        buf.append('"')
        for ch in v:
            if ch == '"':
                buf.append('\\"')
            elif ch == '\\':
                buf.append('\\\\')
            elif ch == '\n':
                buf.append('\\n')
            elif ch == '\t':
                buf.append('\\t')
            else:
                buf.append(ch)
        buf.append('"')
    elif isinstance(v, list):
        buf.append('[')
        for i, e in enumerate(v):
            if i:
                buf.append(',')
            emit(e, buf)
        buf.append(']')
    elif isinstance(v, dict):
        buf.append('{')
        for i, k in enumerate(sorted(v.keys())):
            if i:
                buf.append(',')
            emit(k, buf)
            buf.append(':')
            emit(v[k], buf)
        buf.append('}')
    else:
        raise ParseError()


def run(data):
    if not data or not data.strip():
        return 'ERR'
    try:
        v = Parser(data).parse()
    except (ParseError, ValueError):
        return 'ERR'
    buf = []
    try:
        emit(v, buf)
    except ParseError:
        return 'ERR'
    return ''.join(buf)


def selftest():
    cases = [
        ('-33', '-33'),
        ('-0', '0'),
        ('true', 'true'),
        ('null', 'null'),
        ('false', 'false'),
        ('  {"a":1,"b":[2,3]}  ', '{"a":1,"b":[2,3]}'),
        ('{"b":1,"a":2}', '{"a":2,"b":1}'),
        ('{"a":1,"a":2}', '{"a":2}'),
        ('["\\\\9\\u4e2d/",  null\n]', '["\\\\9中/",null]'),
        ('"x\\ny\\tz"', '"x\\ny\\tz"'),
        ('"\u4e2d"', '"\u4e2d"'),
        ('01', 'ERR'),
        ('1 2', 'ERR'),
        ('', 'ERR'),
        ('   ', 'ERR'),
        ('"\\q"', 'ERR'),
        ('"\\u001f"', 'ERR'),
        ('"\\u0041"', '"A"'),
        ('[1,]', 'ERR'),
        ('{"a":}', 'ERR'),
        ('{"a" 1}', 'ERR'),
        ('123abc', 'ERR'),
        ('"unterminated', 'ERR'),
        ('[1,2]]', 'ERR'),
        ('+1', 'ERR'),
        ('--1', 'ERR'),
        ('nul', 'ERR'),
        ('"a\tb"', 'ERR'),
    ]
    failed = 0
    for inp, exp in cases:
        got = run(inp)
        ok = got == exp
        if not ok:
            failed += 1
            print('FAIL: %r -> %r (expected %r)' % (inp, got, exp))
    if failed:
        print('FAIL %d/%d' % (failed, len(cases)))
        return 1
    print('PASS %d/%d' % (len(cases), len(cases)))
    return 0


def main():
    if '--selftest' in sys.argv[1:]:
        sys.exit(selftest())
    data = sys.stdin.read()
    sys.stdout.write(run(data) + '\n')


if __name__ == '__main__':
    main()
```

已实测(命令: `printf -- '["\\\\9\\u4e2d/",  null\n]' | python3 main.py` 与 `python3 main.py --selftest`),自检 **PASS 28/28**,退出码 0;两个公开用例均输出与期望逐字节一致(`-33`→`-33`;数组→`["\\9中/",null]`)。核心不变式覆盖:数字前导零/多余内容/非法转义/`\uXXXX < 0x20`/裸控制字符/空输入均判 ERR,对象重复键后者覆盖、键按码点升序。

